// src/components/Dashboard.jsx
import React, { useEffect, useState } from "react";
import "./CSS/Dashboard.css";
import { useNavigate } from "react-router-dom";

function Dashboard() {
  const [senders, setSenders] = useState([]);
  const [search, setSearch] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    fetch("http://127.0.0.1:5000/get-users")
      .then((res) => res.json())
      .then((data) => {
        if (data.success) {
          setSenders(data.users);
        }
      })
      .catch((err) => console.error("Error fetching users:", err));
  }, []);

  const handleLogout = () => {
    localStorage.clear();
    navigate("/login");
  };

  const handleUserClick = (email) => {
    navigate("/view-send-messages", { state: { peerEmail: email } });
  };

  const filteredUsers = senders.filter((email) =>
    email.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <input
          type="text"
          className="dashboard-search"
          placeholder="Search by sender email"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <button className="dashboard-logout" onClick={handleLogout}>
          Logout
        </button>
      </header>

      <main className="dashboard-content">
        <h2>View Messages Of Users</h2>
        <div className="user-list">
          {filteredUsers.length > 0 ? (
            filteredUsers.map((email, idx) => (
              <div
                key={idx}
                className="user-card"
                onClick={() => handleUserClick(email)}
              >
                {email}
              </div>
            ))
          ) : (
            <p className="no-users">No users found.</p>
          )}
        </div>
      </main>
    </div>
  );
}

export default Dashboard;
